<?php
/** @var callable $e */
/** @var array<string, list<\Zoosper\Settings\Definition\SettingsSection>> $categories */
/** @var int $sectionCount */
/** @var array<string, \Zoosper\Settings\Value\SettingValue> $effectiveValues */
/** @var string $scopeLabel */
/** @var string $scopeType */
/** @var string $scopeKey */
/** @var list<string> $websiteOptions */
/** @var list<string> $storeOptions */
/** @var array<int, object> $siteOptions */
/** @var string $csrfToken */
/** @var bool $showPaths */
$categoryLabels = ['general' => 'General', 'communication' => 'Communication', 'content' => 'Content', 'design' => 'Design', 'commerce' => 'Commerce', 'security' => 'Security', 'advanced' => 'Advanced'];
$categoryDescriptions = ['general' => 'Site-wide defaults and foundational behaviour.', 'communication' => 'Email delivery, notifications and outbound communication.', 'content' => 'Content authoring, pages and publishing behaviour.', 'design' => 'Themes, templates and presentation.', 'commerce' => 'Orders, catalogues and transactional behaviour.', 'security' => 'Authentication, privacy and protection controls.', 'advanced' => 'Administration and technical platform behaviour.'];
$categoryOrder = ['general', 'communication', 'content', 'design', 'commerce', 'security', 'advanced'];
uksort($categories, static function (string $a, string $b) use ($categoryOrder): int {
    $aIndex = array_search($a, $categoryOrder, true);
    $bIndex = array_search($b, $categoryOrder, true);
    return [is_int($aIndex) ? $aIndex : 999, $a] <=> [is_int($bIndex) ? $bIndex : 999, $b];
});
$firstCategory = (string) (array_key_first($categories) ?? 'advanced');
$settingsModules = [];
foreach ($categories as $moduleSections) {
    foreach ($moduleSections as $moduleSection) {
        $settingsModules[$moduleSection->module] = $moduleSection->module;
    }
}
ksort($settingsModules);
?>
