          <?php if($editable!==[]): ?><form method="post" action="/admin/settings/save" data-settings-form data-section-label="<?= $e($section->label) ?>"><input type="hidden" name="_csrf_token" value="<?= $e($csrfToken) ?>"><input type="hidden" name="section" value="<?= $e($section->id) ?>"><input type="hidden" name="scope" value="<?= $e($scopeType) ?>"><input type="hidden" name="scope_key" value="<?= $e($scopeKey) ?>"><?php endif; ?>
          <?php foreach($section->groups as $group): ?>
            <details class="settings-group" id="group-<?= $e($section->id.'-'.$group->id) ?>" data-settings-group data-group-key="<?= $e($section->id.'.'.$group->id) ?>" <?= $group->openByDefault ? 'data-open-default open' : '' ?>>
              <summary><span><?= $e($group->label) ?><?php if($group->description!==''): ?><small class="settings-muted"> · <?= $e($group->description) ?></small><?php endif; ?></span><span class="settings-badge"><?= $e((string)count($group->settings)) ?></span></summary>
              <div class="settings-group-body">
              <?php foreach($group->settings as $setting): $effective=$effectiveValues[$setting->path]; ?>
                <div class="settings-field" id="setting-<?= $e(str_replace(['.', '_'], '-', $setting->path)) ?>" data-setting-field="<?= $e($setting->path) ?>" data-setting-source="<?= $e($effective->source) ?>" data-setting-readonly="<?= $effective->readOnly ? 'true' : 'false' ?>" data-setting-editable="<?= in_array($setting,$editable,true) ? 'true' : 'false' ?>"><div class="settings-field-row"><div class="settings-field-heading"><strong><?= $e($setting->label) ?></strong><a class="settings-icon-button" href="#setting-<?= $e(str_replace(['.', '_'], '-', $setting->path)) ?>" aria-label="Link to <?= $e($setting->label) ?>">Link</a><?php if($showPaths): ?><button class="settings-icon-button" type="button" data-copy-setting-path="<?= $e($setting->path) ?>">Copy path</button><?php endif; ?></div><span class="settings-badge"><?= $e($setting->type) ?></span></div><?php if($showPaths): ?><code><?= $e($setting->path) ?></code><?php endif; ?><?php if($setting->description!==''): ?><p class="settings-muted"><?= $e($setting->description) ?></p><?php endif; ?><div class="settings-meta"><span class="settings-badge">Source: <?= $e(ucfirst($effective->source)) ?></span><?php if($effective->readOnly): ?><span class="settings-badge">Read-only</span><?php endif; ?><?php if($effective->secret): ?><span class="settings-badge">Secret</span><?php endif; ?></div><strong>Effective value</strong><br><code><?= $effective->secret?'••••••••':$e($effective->value===null?'Not set':(is_bool($effective->value)?($effective->value?'Enabled':'Disabled'):(string)$effective->value)) ?></code><?php if($effective->explanation!==null): ?><p class="settings-muted" data-field-explanation><?= $e($effective->explanation) ?></p><?php endif; ?>
                <?php if(in_array($setting,$editable,true)): $inputName='settings['.$setting->path.']'; ?>
                  <?php if($setting->type==='boolean'): ?><span class="settings-edit-control"><input type="hidden" name="<?= $e($inputName) ?>" value="0"><label><input type="checkbox" name="<?= $e($inputName) ?>" value="1" <?= in_array((string)$effective->value,['1','true'],true)||$effective->value===true?'checked':'' ?>> Enabled</label>
                  <?php elseif($setting->type==='textarea'): ?><span class="settings-edit-control"><textarea class="settings-input" name="<?= $e($inputName) ?>" rows="4"><?= $e($effective->value===null?'':(string)$effective->value) ?></textarea></span><span class="settings-print-value"><?= $e($effective->value===null?'Not set':(string)$effective->value) ?></span>
                  <?php elseif($setting->type==='select'): ?><span class="settings-edit-control"><select class="settings-input" name="<?= $e($inputName) ?>"><?php foreach($setting->options as $option): ?><option value="<?= $e($option) ?>" <?= (string)$effective->value===$option?'selected':'' ?>><?= $e($option) ?></option><?php endforeach; ?></select></span><span class="settings-print-value"><?= $e($effective->value===null?'Not set':(string)$effective->value) ?></span>
                  <?php elseif($setting->type==='multiselect'): $selectedValues=is_string($effective->value)?json_decode($effective->value,true):[];$selectedValues=is_array($selectedValues)?array_map('strval',$selectedValues):[]; ?><span class="settings-edit-control"><select class="settings-input" name="<?= $e($inputName) ?>[]" multiple><?php foreach($setting->options as $option): ?><option value="<?= $e($option) ?>" <?= in_array($option,$selectedValues,true)?'selected':'' ?>><?= $e($option) ?></option><?php endforeach; ?></select></span><span class="settings-print-value"><?= $e($effective->value===null?'Not set':(string)$effective->value) ?></span>
                  <?php else: $inputType=match($setting->type){'email'=>'email','url'=>'url','integer'=>'number','decimal'=>'number',default=>'text'}; ?><span class="settings-edit-control"><input class="settings-input" type="<?= $e($inputType) ?>" name="<?= $e($inputName) ?>" value="<?= $e($effective->value===null?'':(string)$effective->value) ?>" <?= $setting->type==='integer'?'step="1"':($setting->type==='decimal'?'step="any"':'') ?>></span><span class="settings-print-value"><?= $e($effective->value===null?'Not set':(string)$effective->value) ?></span><?php endif; ?>
                  <?php if($effective->source==='database'): ?><button class="settings-clear" type="submit" name="path" value="<?= $e($setting->path) ?>" formaction="/admin/settings/clear" formmethod="post">Use inherited value</button><?php endif; ?>
                <?php endif; ?></div>
              <?php endforeach; ?>
              </div>
            </details>
          <?php endforeach; ?>
          <?php if($editable!==[]): ?><footer class="settings-actions"><span class="settings-muted" data-form-status aria-live="polite">No unsaved changes</span><button class="settings-clear" type="button" data-reset-section disabled>Reset section</button><button class="settings-save" type="submit" data-save-section disabled>Save <?= $e($section->label) ?></button></footer></form><?php endif; ?>
        </article>
      <?php endforeach; ?></section>
    <?php endforeach; ?>
  </main>
</div>
